'use strict';
(() => {
  const root = document.querySelector('#app-root'), phone = document.querySelector('#phone');
  const controls = Object.fromEntries(['screen','scenario','theme','width','scale','platform','actor','stage','failure'].map(k => [k, document.querySelector('#'+k+'-choice')]));
  const s = {screen:'requests', mode:'helper', role:'both',roleDraft:null,roleByActor:{alex:'both',vika:'owner'}, actor:'alex', scenario:'populated', theme:'light', width:'390', scale:'1', platform:'ios', stage:'available', requestId:'luna', back:[], busy:false, fail:false, feedback:'', menu:false, tab:'upcoming', step:0, drafts:{}, reviews:{}, replies:{}, expanded:{}, blocks:{}, messages:[], applications:{}, filters:{city:'Минск',district:'Все районы',date:'Любая дата',when:'Любое время',size:'Любой размер'}, intro:{name:'Александра Левина',city:'Минск',district:'Центральный район',about:'Люблю спокойные прогулки. Умею знакомиться с собакой без спешки.',experience:'Гуляла с собаками друзей: корги и небольшими метисами.',sizes:['small','medium'],areas:'Центральный, Советский',availability:'Будни после 18:00, выходные утром',handling:'Спокойная прогулка на поводке'}, onboardingDone:false,draftPhotos:{},ownerTab:'favorites',ownerEditing:false,ownerIntro:{name:'Виктория Соколова',city:'Минск',district:'Центральный район',about:'Люблю спокойные прогулки с Луной и заранее обсуждаю все детали.',experience:'',sizes:[],areas:'',availability:'',handling:''}};
  const requests = [
    {id:'luna',name:'Луна',kind:'Корги · 2 года · 12 кг',when:'11 октября · 18:30',duration:'40 минут',district:'Центральный район',size:'medium',photo:'pet.jpg',owner:'Виктория Соколова',ownerId:'vika',description:'Нужна спокойная прогулка вечером. Луна любит обнюхивать всё вокруг и сначала немного стесняется.',details:'Привыкла гулять на поводке. Спокойно встречает людей, к другим собакам подходит постепенно.'},
    {id:'richi',name:'Ричи',kind:'Метис · 5 лет · 7 кг',when:'12 октября · 08:00',duration:'30 минут',district:'Советский район',size:'small',owner:'Дмитрий',ownerId:'dima',description:'Ищем помощника для утренней прогулки по знакомому району.',details:'Предпочитает спокойный темп и небольшие маршруты.'},
    {id:'milo',name:'Мило',kind:'Лабрадор · 4 года · 26 кг',when:'12 октября · 19:00',duration:'',district:'Центральный район',size:'large',owner:'Александра Левина',ownerId:'alex',description:'Помогите с вечерней прогулкой. Время можно обсудить.',details:'Дружелюбный, гуляет на поводке.'}
  ];
  const baseReviews = [{id:'r1',author:'Евгения',rating:5,date:'6 октября 2026',body:'Нора вернулась довольная. Александра заранее уточнила привычки собаки и после прогулки написала, как всё прошло.',reply:''},{id:'r2',author:'Дмитрий',rating:5,date:'28 сентября 2026',body:'Договорились о спокойном маршруте. Бруно быстро привык к Александре, всё прошло вовремя.',reply:'Спасибо, Дмитрий! Рада, что Бруно понравилась прогулка.'},{id:'r3',author:'Мария',rating:4,date:'14 сентября 2026',body:'Прогулка прошла хорошо. Вначале мы немного по-разному поняли время встречи, но быстро уточнили его в чате. Мне понравилось, что Александра спросила, какие команды знает Ричи и как он реагирует на других собак. В следующий раз заранее подтвердим время встречи.',reply:''}];
  const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = n => `<i data-lucide="${n}" aria-hidden="true"></i>`;
  const button = (action,label,kind='quiet-action',extra='') => `<button type="button" data-action="${action}" class="${kind}" ${s.busy?'disabled':''} ${extra}>${label}</button>`;
  const shortName = id => id==='alex'?'Александра':id==='vika'?'Виктория':'Дмитрий';
  const fullName = id => s.scenario==='long' ? (id==='alex'?'Александра Константиновна Левина-Воскресенская':id==='vika'?'Виктория Александровна Соколова-Константинопольская':'Дмитрий Александрович Орлов-Константинопольский') : id==='alex'?s.intro.name:id==='vika'?s.ownerIntro.name:'Дмитрий Орлов';
  const avatar = (id,size='') => s.scenario==='long'||s.scenario==='empty'||id==='dima' ? `<span class="avatar ${size}" aria-hidden="true">${id==='alex'?'АЛ':id==='vika'?'ВС':'ДО'}</span>` : `<img class="avatar ${size}" src="walking-assets/${id==='alex'?'owner':'helper'}.jpg" alt="" width="64" height="64">`;
  const pet = r => r.photo&&s.scenario!=='long'?`<img class="pet-avatar" src="walking-assets/${r.photo}" alt="" width="64" height="64">`:`<span class="pet-avatar" aria-hidden="true">${icon('paw-print')}</span>`;
  const current = () => requests.find(r=>r.id===s.requestId)||requests[0];
  const stageName = {available:'Ищет помощника',applied:'Отклик отправлен',selected:'Помощник выбран',active:'Идёт прогулка',awaiting:'Ждёт подтверждения владельца',completed:'Завершена',cancelled:'Отменена'};
  const isOwner = () => current().ownerId===s.actor;
  const assigned = () => s.requestId==='luna'&&['selected','active','awaiting','completed','cancelled'].includes(s.stage);
  const participant = () => assigned()&&(s.actor==='alex'||isOwner());
  function go(screen){if(s.busy)return;s.back.push({screen:s.screen,tab:s.tab});s.screen=screen;s.feedback='';s.menu=false;render(true);}
  function back(){if(s.busy)return;const previous=s.back.pop();s.screen=previous?.screen||'requests';s.tab=previous?.tab||s.tab;s.feedback='';s.menu=false;render(true);}
  function operate(success,error='Не удалось сохранить. Проверьте соединение и попробуйте снова.') {
    if(s.busy)return;
    const previousScreen=s.screen,previousStep=s.step;
    s.busy=true;s.feedback='';s.feedbackError=false;render();
    setTimeout(()=>{
      s.busy=false;
      if(s.fail){s.fail=false;controls.failure.checked=false;s.feedback=error;s.feedbackError=true;render();}
      else{success();render(s.screen!==previousScreen||s.step!==previousStep);}
    },600);
  }
  function status(text,name='clock'){return `<p class="status-line">${icon(name)}<span>${esc(text)}</span></p>`;}
  function notice(){return s.feedback?`<p class="notice ${s.feedbackError?'error':''}" role="${s.feedbackError?'alert':'status'}">${icon('circle-alert')}<span>${esc(s.feedback)}</span></p>`:'';}
  function input(name,label,value='',type='text',extra=''){return `<label for="${name}">${label}<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
  function textarea(name,label,value='',extra=''){return `<label for="${name}">${label}<textarea id="${name}" name="${name}" rows="3" ${extra}>${esc(value)}</textarea></label>`;}
  function nav(){const owner=s.mode==='owner';const items=owner?[['nearby','compass','Рядом'],['people','users','Люди'],['owner-help','paw-print','Выгул'],['chats','message-square','Чаты'],['owner-self','user-round','Я']]:[['requests','list','Запросы'],['my-walks','paw-print','Мои прогулки'],['chats','message-square','Чаты'],['profile','user-round','Я']];return `<nav class="bottom-nav" data-count="${items.length}" aria-label="Разделы PetFriendly">${items.map(([screen,ic,label])=>button('nav:'+screen,`<span class="nav-icon">${icon(ic)}</span><span>${label}</span>`,(screen===s.screen?'active ':'')+'nav-item',screen===s.screen?'aria-current="page"':'')).join('')}</nav>`;}
  function bar(title,top=false){return `<header class="app-bar">${top?'<span class="wordmark">petfriendly<b>.</b></span>':button('back',icon('arrow-left'),'icon-button','aria-label="Назад"')} ${top&&s.role==='both'?button('mode',`${s.mode==='helper'?'Помощник':'Владелец'}${icon('chevron-down')}`,'mode-switch','aria-label="Переключить режим" aria-haspopup="dialog"'):top?`<span class="caption">${s.mode==='helper'?'Помощник':'Владелец'}</span>`:`<span class="bar-title">${title}</span>`}${button('theme',icon(s.theme==='light'?'moon':'sun'),'icon-button',`aria-label="${s.theme==='light'?'Тёмная':'Светлая'} тема"`)}</header>`;}
  function page(title,subtitle,content,top=false,navVisible=false){return bar(title,top)+`<main class="page screen-${s.screen}" tabindex="-1"><div class="intro"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${notice()}${content}</main>`+(navVisible?nav():'');}
  function stateBlock(kind,emptyTitle,emptyText){if(s.scenario==='loading')return `<section class="empty-state" aria-busy="true"><p role="status">Загружаем ${kind}…</p><div class="skeletons" aria-hidden="true"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></section>`;if(s.scenario==='error'||s.scenario==='unavailable')return `<section class="empty-state"><h2>${s.scenario==='error'?'Не удалось загрузить '+kind:kind[0].toUpperCase()+kind.slice(1)+' недоступны'}</h2><p>Не удалось получить данные. Это не означает, что их нет.</p>${button('retry',s.busy?'Загружаем…':'Повторить загрузку','soft-action')}</section>`;if(s.scenario==='empty')return `<section class="empty-state"><h2>${emptyTitle}</h2><p>${emptyText}</p>${button('requests-home','Посмотреть запросы','soft-action')}</section>`;return '';}
  function roleScreen(){return page('Как вы хотите участвовать?','Один аккаунт для вас и ваших прогулок.',`<form data-form="role" class="form-group"><fieldset ${s.busy?'disabled':''}><legend class="sr-only">Ваша роль</legend>${[['owner','Владелец питомца','Ищите места, общайтесь и просите о помощи.'],['helper','Помощник по выгулу','Находите запросы и гуляйте с чужими питомцами. Свой питомец не нужен.'],['both','Обе роли','Помогайте другим и пользуйтесь всеми разделами владельца.']].map(([val,title,desc])=>`<label class="role-option"><input type="radio" name="role" value="${val}" ${(s.roleDraft||s.role)===val?'checked':''}><div><strong>${title}</strong><p>${desc}</p></div></label>`).join('')}</fieldset><p class="caption">Выбор можно изменить в профиле. Переписки и история останутся в вашем аккаунте.</p><button class="primary-action" ${s.busy?'disabled':''}>${s.busy?'Сохраняем…':'Продолжить'}</button></form>`);}
  const editingIntro=()=>s.actor==='alex'?s.intro:s.ownerIntro;
  function onboarding(){const intro=editingIntro();const identity=s.step===0;return page(s.ownerEditing?'Редактировать профиль':identity?'Познакомимся?':'Какие прогулки вам подходят?',identity?'Расскажите о себе. Питомец для регистрации не нужен.':'Можно заполнить сейчас или вернуться в профиле.',`<form data-form="onboarding" class="form-group"><fieldset ${s.busy?'disabled':''}>${identity?`<div class="identity">${avatar(s.actor)}<div class="identity-copy"><strong>Фото профиля</strong><p class="caption">Необязательно. Пока покажем инициалы.</p>${button('photo','Выбрать фото','quiet-action')}</div></div>${input('name','Имя',intro.name,'text','required maxlength="100"')}${input('city','Город',intro.city,'text','required maxlength="80"')}${input('district','Публичный район · необязательно',intro.district,'text','maxlength="100"')}<p class="caption">Показываем район, а не ваш точный адрес.</p>${textarea('about','Коротко о себе',intro.about,'maxlength="500"')}${s.ownerEditing?'':textarea('experience','Опыт с животными · необязательно',intro.experience,'maxlength="500"')}`:`<p class="section-title">Размер собак</p><div class="choice-grid">${[['small','До 10 кг'],['medium','10–25 кг'],['large','Больше 25 кг']].map(([value,label])=>`<label class="choice"><input type="checkbox" name="sizes" value="${value}" ${intro.sizes.includes(value)?'checked':''}>${label}</label>`).join('')}</div>${input('areas','Районы, где можете помочь',intro.areas,'text','maxlength="150"')}${textarea('availability','Когда вам удобно',intro.availability,'maxlength="300"')}<details class="disclosure"><summary>Предпочтения в обращении с собакой</summary>${textarea('handling','Что для вас важно',intro.handling,'maxlength="300"')}<p class="caption">Например, спокойный темп или опыт с активными собаками. Это описание предпочтений, не подтверждение навыков.</p></details>`}</fieldset><button class="primary-action" ${s.busy?'disabled':''}>${s.busy?'Сохраняем…':s.ownerEditing?'Сохранить профиль':identity?'Продолжить':'Открыть запросы'}</button>${!identity?button('onboard-skip','Заполнить позже'):''}</form>`);}
  function ownerRating(id){if(s.scenario==='unavailable')return 'Репутация владельца недоступна';if(s.scenario==='empty'||s.scenario==='unrated'||id==='dima')return 'Пока нет отзывов как о владельце';return `${icon('star')} ${id==='vika'?(s.reviews.owner?'4,9':'4,8'):'5,0'} из 5 · ${id==='vika'?(s.reviews.owner?'7':'6'):'2'} отзывов как о владельце`;}
  function requestRow(r){const st=r.id==='luna'?s.stage:s.applications[s.actor+':'+r.id]?'applied':'available';return `<article class="request-row"><div class="request-head">${pet(r)}<div class="pet-copy"><h2>${r.name}</h2><p>${r.kind}</p></div></div><p class="request-meta">${icon('calendar-days')}<span>${r.when}${r.duration?' · '+r.duration:''}</span></p><p class="request-meta">${icon('map-pin')}<span>${r.district}</span></p><p class="request-description">${esc(s.scenario==='long'?r.description+' '+r.details:r.description)}</p><div class="owner-row">${avatar(r.ownerId,'small')}<div><strong>${esc(fullName(r.ownerId))}</strong><p class="caption">${ownerRating(r.ownerId)}</p></div></div><div class="request-footer">${status(stageName[st],st==='applied'?'send':'clock')}${button('request:'+r.id,'Посмотреть запрос'+icon('arrow-right'),'soft-action')}</div></article>`;}
  function requestsScreen(){const filter=(key,label,options)=>`<label class="filter-control">${label}<select data-filter="${key}" ${s.busy?'disabled':''}>${options.map(x=>`<option ${s.filters[key]===x?'selected':''}>${x}</option>`).join('')}</select></label>`;const filtered=requests.filter(r=>r.ownerId!==s.actor&&(s.filters.date==='Любая дата'||r.when.startsWith(s.filters.date))&&(s.filters.district==='Все районы'||r.district===s.filters.district)&&(s.filters.size==='Любой размер'||r.size==={'До 10 кг':'small','10–25 кг':'medium','Больше 25 кг':'large'}[s.filters.size])&&(s.filters.when==='Любое время'||(s.filters.when==='Утро'?r.when.includes('08:'):!r.when.includes('08:'))));const noCity=s.filters.city!=='Минск';return page('Запросы на прогулку','Найдите прогулку, с которой можете помочь.',`<div class="filters">${filter('city','Город',['Минск','Гродно'])}${filter('district','Район',['Все районы','Центральный район','Советский район'])}</div><details class="disclosure"><summary>Дата, время и размер${[s.filters.date!=='Любая дата',s.filters.when!=='Любое время',s.filters.size!=='Любой размер'].filter(Boolean).length?' · '+[s.filters.date!=='Любая дата',s.filters.when!=='Любое время',s.filters.size!=='Любой размер'].filter(Boolean).length:''}</summary><div class="filters">${filter('date','Дата',['Любая дата','11 октября','12 октября'])}${filter('when','Время',['Любое время','Утро','Вечер'])}${filter('size','Размер собаки',['Любой размер','До 10 кг','10–25 кг','Больше 25 кг'])}</div></details>${['loading','error','unavailable'].includes(s.scenario)?stateBlock('запросы','',''):s.scenario==='empty'||noCity||!filtered.length?`<section class="empty-state"><h2>Подходящих запросов пока нет</h2><p>Попробуйте другой район, время или размер собаки.</p>${button('reset-filters','Сбросить фильтры','soft-action')}</section>`:`<div class="request-list">${filtered.map(requestRow).join('')}</div>`}`,true,true);}
  function candidate(id){return `<section class="section"><div class="identity">${avatar(id)}<div class="identity-copy"><h2>${esc(fullName(id))}</h2><p class="caption">${id==='alex'?'4,7 из 5 · 3 отзыва · 18 выгулов':'Пока нет отзывов'}</p></div></div>${button('candidate:'+id,'Профиль помощника'+icon('chevron-right'),'row-button')}${id==='alex'?button('select-helper','Выбрать Александру','primary-action'):button('candidate:'+id,'Посмотреть опыт','soft-action')}</section>`;}
  function requestDetail(){const r=current(), st=r.id==='luna'?s.stage:s.applications[s.actor+':'+r.id]?'applied':'available';const forbidden=['cancelled','completed'].includes(st);let action='';if(isOwner()){action=st==='applied'?`<h2 class="section-title">Отклики · 2</h2>${candidate('alex')}${candidate('dima')}`:assigned()?button('agreement','Открыть договорённость','primary-action'):`<p class="notice">${icon('users')}Отклики появятся здесь. Решение о выборе помощника принимаете вы.</p>`;}else if(r.ownerId!==s.actor){if(forbidden)action=`<p class="notice">${icon('circle-minus')}Запрос больше не принимает отклики.</p>`;else if(st==='available')action=button('apply',s.busy?'Отправляем…':'Откликнуться на запрос','primary-action')+'<p class="caption">Отклик не означает, что вас выбрали. Решение принимает владелец.</p>';else if(st==='applied')action=`<p class="notice">${icon('send')}Владелец получил ваш отклик. Дождитесь его решения.</p>${button('withdraw','Отозвать отклик')}`;else action=button('agreement','Открыть договорённость','primary-action');}return page('Запрос на прогулку','',`${stateBlock('запрос', 'Запрос недоступен','Он мог быть закрыт владельцем.')||`<div class="request-head">${pet(r)}<div class="pet-copy"><h2>${r.name}</h2><p>${r.kind}</p></div></div>${status(stageName[st])}<p class="request-meta">${icon('calendar-days')}<span>${r.when}${r.duration?' · '+r.duration:''}</span></p><p class="request-meta">${icon('map-pin')}<span>Минск · ${r.district}</span></p><h2 class="section-title">О прогулке</h2><p>${esc(r.description)}</p><details class="disclosure"><summary>Характер и привычки</summary><p>${esc(r.details)}</p></details>${button('owner:'+r.ownerId,`${avatar(r.ownerId,'small')}<span><strong>${esc(fullName(r.ownerId))}</strong><span class="caption">${ownerRating(r.ownerId)}</span></span>${icon('chevron-right')}`,'row-button')}<p class="caption">Адрес передачи и личные инструкции доступны только участникам после выбора помощника.</p>${action}`}`);}
  function agreementRow(history=false){const r=requests[0];return `<article class="agreement-row"><div class="request-head">${pet(r)}<div class="pet-copy"><h2>${r.name}</h2><p>${r.when}</p></div></div>${status(stageName[s.stage],s.stage==='completed'?'circle-check':'clock')}<p class="caption">Вы — ${s.actor==='alex'?'помощник':'владелец'}</p>${button('agreement',history?'Посмотреть прогулку':'Открыть прогулку'+icon('chevron-right'),'row-button')}</article>`;}
  function myWalks(){const apps=requests.filter(r=>r.id==='luna'?s.stage==='applied':s.applications[s.actor+':'+r.id]), app=apps.length>0, has=assigned()&&s.actor==='alex', history=['completed','cancelled'].includes(s.stage);let content;if(['loading','error','unavailable'].includes(s.scenario))content=stateBlock('прогулки','','');else if(s.scenario==='empty')content=stateBlock('прогулки','Первый выгул впереди','Отправьте отклик. Прогулка появится здесь, когда владелец выберет вас.');else if(s.tab==='applications')content=app?apps.map(r=>`<article class="agreement-row"><h2>${r.name} · ${r.when}</h2>${status('Отклик отправлен','send')}<p>Владелец ещё не выбрал помощника. Это не договорённость.</p>${button('request:'+r.id,'Посмотреть запрос','soft-action')}</article>`).join(''):`<section class="empty-state"><h2>Пока нет откликов</h2><p>Выберите подходящий запрос. Владелец увидит ваш профиль и опыт.</p>${button('requests-home','Найти запрос','primary-action')}</section>`;else if((s.tab==='history'&&history)||(s.tab==='upcoming'&&has&&!history))content=agreementRow(history);else content=`<section class="empty-state"><h2>${s.tab==='history'?'Завершённые прогулки появятся здесь':'Пока нет договорённостей'}</h2><p>${s.tab==='history'?'Здесь останутся завершённые и отменённые договорённости.':'Отправленный отклик остаётся в разделе «Отклики», пока владелец не выберет вас.'}</p>${button('requests-home','Найти запрос','primary-action')}</section>`;return page('Мои прогулки','Договорённости и следующий шаг.',`<div class="tabs" role="tablist" aria-label="Прогулки">${[['upcoming','Предстоящие'],['applications','Отклики']].map(([val,label])=>button('tab:'+val,label,'',`role="tab" aria-selected="${s.tab===val}" tabindex="${s.tab===val?'0':'-1'}"`)).join('')}</div>${s.tab==='history'?'<h2 class="section-title">История</h2>':''}${content}${button('tab:'+ (s.tab==='history'?'upcoming':'history'),s.tab==='history'?'К предстоящим прогулкам':'История прогулок'+icon('chevron-right'),'row-button')}`,true,true);}
  function agreement(){if(!assigned())return page('Прогулка с Луной','',`<section class="empty-state"><h2>${s.stage==='applied'?'Отклик ещё рассматривают':'Помощник пока не выбран'}</h2><p>Договорённость появится после решения владельца.</p>${button('request:luna','Открыть запрос','primary-action')}</section>`);const role=isOwner()?'Владелец':'Помощник', helper=s.actor==='alex';let next='';if(s.stage==='selected')next=helper?button('start',s.busy?'Начинаем…':'Начать прогулку','primary-action'):'<p class="notice">Помощник начнёт прогулку после передачи питомца.</p>';else if(s.stage==='active')next=helper?button('finish',s.busy?'Сохраняем…':'Завершить прогулку','primary-action'):'<p class="notice">Идёт прогулка. Помощник сообщит о завершении.</p>';else if(s.stage==='awaiting')next=helper?'<p class="notice">Вы завершили прогулку. Ждём подтверждения Виктории.</p>':button('confirm',s.busy?'Подтверждаем…':'Подтвердить завершение','primary-action');else if(s.stage==='completed'){const key=helper?'owner':'helper';next=s.reviews[key]?`<p class="notice">${icon('circle-check')}Ваш отзыв опубликован.</p>`:button('review',helper?'Оставить отзыв владельцу':'Оставить отзыв помощнику','primary-action');}else next='<p class="notice">Договорённость отменена. Новых действий по прогулке нет.</p>';return page('Прогулка с Луной',`Вы — ${role.toLowerCase()}`,`${stateBlock('договорённости','Пока нет договорённости','Владелец должен выбрать помощника.')||`<div class="request-head">${pet(requests[0])}<div class="pet-copy"><h2>Луна</h2><p>11 октября · 18:30 · 40 минут</p></div></div>${status(stageName[s.stage],s.stage==='completed'?'circle-check':'clock')}<div class="identity">${avatar(helper?'vika':'alex','small')}<div class="identity-copy"><strong>${esc(fullName(helper?'vika':'alex'))}</strong><p class="caption">${helper?'Владелец питомца':'Назначенный помощник'}</p></div></div><div class="section">${next}</div>${button('chat','Чат прогулки'+icon('message-square'),'row-button')}${participant()&&s.stage!=='cancelled'?`<details class="disclosure"><summary>${icon('lock-keyhole')}Детали передачи питомца</summary><p>Встреча у входа в парк. Сторону входа согласовали в чате.</p><p>Луна гуляет на поводке. Остальные привычки обсудим перед встречей.</p><p class="caption">Эти сведения видны только Виктории и назначенному помощнику.</p></details>`:''}<details class="disclosure"><summary>Этапы прогулки</summary><ol><li>Владелец выбрал помощника</li><li>Помощник начинает и завершает прогулку</li><li>Владелец подтверждает завершение</li><li>Оба участника могут оставить отзыв</li></ol></details>`}`);}
  function chats(){return page('Чаты','Хороший разговор — начало спокойной прогулки.',`${stateBlock('переписки','Пока нет переписок','Обсудите прогулку после выбора помощника.')||`<div class="section">${button(participant()?'chat':'direct-chat:'+(s.actor==='alex'?'vika':'alex'),`${avatar(s.actor==='alex'?'vika':'alex','small')}<span><strong>${esc(shortName(s.actor==='alex'?'vika':'alex'))}${participant()?' · Луна':''}</strong><span class="caption">${participant()?(s.messages.length?esc(s.messages.at(-1).text):'Договоримся о встрече у парка.'):'Давайте обсудим подходящую прогулку.'} · 17:45</span></span>${icon('chevron-right')}`,'row-button')}${button('direct-chat:dima',`${avatar('dima','small')}<span><strong>Дмитрий</strong><span class="caption">Спасибо за ответ! · 10:20</span></span>${icon('chevron-right')}`,'row-button')}</div>`}`,true,true);}
  const messageKey=()=> 'message:'+s.actor+':'+(s.screen==='direct-chat'?'direct:'+s.contactTarget:'luna');
  function chat(direct=false){const chatUnavailable=['loading','error','unavailable'].includes(s.scenario);const permitted=direct||participant();if(!permitted)return page('Чат прогулки','',`<section class="empty-state"><h2>Помощник ещё не выбран</h2><p>Чат договорённости откроется только владельцу и выбранному помощнику.</p>${button('request:luna','Вернуться к запросу','primary-action')}</section>`);const messages=s.scenario==='empty'?[]:direct?[{actor:s.contactTarget||'dima',text:'Здравствуйте! Давайте обсудим подходящую прогулку.',time:'10:20'},...s.messages.filter(m=>m.direct&&[m.actor,m.target].includes(s.actor)&&[m.actor,m.target].includes(s.contactTarget))]:[{actor:'vika',text:'Здравствуйте! Давайте встретимся у входа в парк в 18:30.',time:'17:40'},{actor:'alex',text:'Здравствуйте, Виктория! Да, буду вовремя. Расскажите, пожалуйста, какие команды знает Луна.',time:'17:45'},...s.messages.filter(m=>!m.direct)];return bar(direct?esc(shortName(s.contactTarget||'dima')):'Прогулка с Луной')+`<main class="page chat-page" tabindex="-1">${direct?'':button('agreement',`<span><strong>Луна · 11 октября, 18:30</strong><span class="caption">${stageName[s.stage]} · Вы — ${isOwner()?'владелец':'помощник'}</span></span>${icon('chevron-right')}`,'context-row')}${notice()}${['loading','error','unavailable'].includes(s.scenario)?stateBlock('сообщения','',''):''}<div class="chat-log" aria-label="Сообщения">${s.scenario==='empty'?'<p class="caption">Напишите участнику прогулки, чтобы согласовать встречу.</p>':''}${['loading','error','unavailable'].includes(s.scenario)?'':messages.map(m=>`<article class="message ${m.actor===s.actor?'outgoing':'incoming'}"><p class="message-meta">${esc(shortName(m.actor))} · ${m.time||'18:05'}</p>${m.photo?'<img src="walking-assets/pet.jpg" alt="Луна после прогулки" width="160" height="160">':''}${m.text?`<p>${esc(m.text)}</p>`:''}</article>`).join('')}</div>${s.draftPhotos[messageKey()]?`<div class="attachment-preview"><img src="walking-assets/pet.jpg" width="72" height="72" alt="Фото Луны готово к отправке">${button('remove-photo','Убрать фото')}</div>`:''}<label for="message-text" class="caption">Сообщение</label><form data-form="message" class="composer">${button('message-photo',icon('image'),'icon-button','aria-label="Прикрепить фото"')}<textarea id="message-text" name="message" rows="2" placeholder="Сообщение" maxlength="2000" ${s.busy?'disabled':''}>${esc(s.drafts[messageKey()]||'')}</textarea><button class="icon-button" aria-label="Отправить сообщение" ${s.busy||chatUnavailable?'disabled':''}>${icon(s.busy?'clock':'arrow-up')}</button></form><p class="caption">${s.busy?'Отправляем…':chatUnavailable?'Отправка станет доступна после загрузки переписки.':'Фото и текст доступны участникам переписки.'}</p></main>`;}
  function facts(role='helper',id='alex'){if(['loading','error','unavailable'].includes(s.scenario))return stateBlock('репутация','','');const owner=role==='owner';const fresh=s.scenario==='empty'||s.scenario==='unrated'||(owner&&id==='dima');const review=owner?(id==='vika'?s.reviews.owner:null):s.reviews.helper;return `<div class="facts" aria-label="Репутация ${owner?'как владельца':'как помощника'}"><div class="fact">${fresh?'<strong>Пока нет отзывов</strong>':`<p aria-label="Средняя оценка ${owner?(id==='alex'?'5,0':(review?'4,9':'4,8')):(review?'4,8':'4,7')} из 5">${icon('star')}<strong>${owner?(id==='alex'?'5,0':(review?'4,9':'4,8')):(review?'4,8':'4,7')}</strong><span class="caption">из 5</span></p><p class="caption">${owner?(id==='alex'?'2':(review?'7':'6')):(review?'4':'3')} опубликованных отзывов</p>`}</div>${!owner?`<div class="fact"><strong>${s.scenario==='empty'?0:s.scenario==='unrated'?5:s.stage==='completed'?19:18}</strong><p class="caption">завершённых выгулов как помощник</p></div>`:''}</div>`;}
  function reviewTile(r,replyAllowed=false){const text=s.scenario==='long'?r.body+' '+baseReviews[2].body:r.body;const expanded=s.expanded[r.id];const reply=s.replies[r.id]??r.reply;return `<article class="review"><div class="review-head"><span class="avatar small" aria-hidden="true">${r.author.slice(0,1)}</span><div class="author"><strong>${esc(s.scenario==='long'?r.author+(r.author==='Дмитрий'?' Александрович Константинопольский':' Александровна Константинопольская'):r.author)}</strong><p class="date">${r.date}</p></div><span class="review-rating" aria-label="${r.rating} из 5">${icon('star')}${r.rating} из 5</span>${button('report:review:'+r.id,icon('ellipsis'),'icon-button','aria-label="Пожаловаться на отзыв '+esc(r.author)+'"')}</div>${text?`<p>${esc(!expanded&&text.length>200?text.slice(0,170)+'…':text)}</p>`:''}${text.length>200?button('expand:'+r.id,expanded?'Свернуть отзыв':'Читать полностью','quiet-action',`aria-expanded="${!!expanded}"`):''}${reply?`<div class="helper-reply"><strong>${replyAllowed?'Ваш ответ':'Ответ '+(s.screen==='owner-profile'?'владельца':'помощника')}</strong><p>${esc(reply)}</p></div>`:''}${replyAllowed?button('reply:'+r.id,reply?'Изменить ответ':'Ответить на отзыв'):''}${s.replyId===r.id?`<form data-form="reply" data-review="${r.id}" class="form-group">${textarea('reply-text','Ваш ответ',s.drafts['reply:'+r.id]??reply,'maxlength="1000" required '+(s.busy?'disabled':''))}<p class="caption">Ответ публичный. Не указывайте адреса, контакты и инструкции по уходу.</p><button class="primary-action" ${s.busy?'disabled':''}>${s.busy?'Публикуем…':'Опубликовать ответ'}</button>${button('close-reply','Отмена')}</form>`:''}</article>`;}
  function helperProfile(publicView=false){const id=publicView?(s.candidateId||'dima'):s.actor;const own=s.actor===id;const intro=id==='alex'?s.intro:id==='vika'?s.ownerIntro:{city:'Минск',district:'Советский район',about:'Люблю спокойные утренние прогулки с небольшими собаками.',experience:'Гулял с небольшими собаками друзей. Готов заранее обсудить привычки питомца.',sizes:['small'],areas:'Советский район',availability:'По субботам утром',handling:'Один питомец за прогулку, спокойный темп'};const received=s.reviews.helper?{id:'luna-helper',author:'Виктория',date:'11 октября 2026',rating:s.reviews.helper.rating,body:s.reviews.helper.body,reply:''}:null;const reviews=id!=='alex'||['empty','unrated','loading','error','unavailable'].includes(s.scenario)?[]:[...(received?[received]:[]),...baseReviews];return page(own?'Ваш профиль помощника':'Профиль помощника','',`<div class="identity">${avatar(id)}<div class="identity-copy"><h2>${esc(fullName(id))}</h2><p class="caption">${esc(intro.city)}${intro.district.trim()?' · '+esc(intro.district):''}</p></div></div>${intro.about.trim()?`<p>${esc(intro.about)}</p>`:''}<h2 class="section-title">Опыт как помощника</h2>${id!=='alex'&&!['loading','error','unavailable'].includes(s.scenario)?`<div class="facts"><p>Пока нет отзывов</p><p>${s.scenario==='unrated'?5:0} завершённых выгулов</p></div>`:facts()}<p class="caption">Отзывы помогают принять решение, но не гарантируют безопасность.</p>${own?button('edit-profile','Редактировать профиль'+icon('pencil'),'row-button'):button('direct-chat:'+id,s.busy?'Открываем…':'Обсудить прогулку','primary-action')}${!own?button('profile-menu','Действия с профилем'+icon('ellipsis'),'row-button','aria-expanded="'+s.menu+'"'):''}${s.menu&&!own?`<div class="menu">${button('report:profile:'+id,'Пожаловаться на профиль')}${button('block:'+id,'Заблокировать','quiet-action destructive')}</div>`:''}<details class="disclosure"><summary>Предпочтения и доступность</summary><p>${esc(intro.experience)}</p><p>Размер собак: ${intro.sizes.map(v=>({'small':'до 10 кг','medium':'10–25 кг','large':'больше 25 кг'}[v])).join(', ')||'не указан'}</p><p>Районы: ${esc(intro.areas||'не указаны')}</p><p>${esc(intro.availability||'Время обсудим в чате')}</p><p>${esc(intro.handling)}</p></details>${own&&s.role==='both'?button('owner-reputation','Репутация как владелец'+icon('chevron-right'),'row-button'):''}<h2 class="section-title">Отзывы о помощи с выгулом</h2>${id!=='alex'&&!['loading','error','unavailable'].includes(s.scenario)?'<p>Первый отзыв ещё впереди.</p>':reviews.length?reviews.map(r=>reviewTile(r,own)).join(''):['loading','error','unavailable'].includes(s.scenario)?'<p class="caption">Отзывы появятся после загрузки данных.</p>':'<p>Пока нет отзывов. Владельцы смогут оставить отзыв после подтверждённой прогулки.</p>'}${own?button('roles','Роли и режим'+icon('chevron-right'),'row-button'):''}`,own,own);}
  function ownerProfile(self=false){const id=self?s.actor:(s.ownerId||current().ownerId),own=id===s.actor;const review=id==='vika'?s.reviews.owner:null;return page(own?'Ваш профиль владельца':'Профиль владельца','',`<div class="identity">${avatar(id)}<div class="identity-copy"><h2>${esc(fullName(id))}</h2><p class="caption">Минск · ${id==='dima'?'Советский район':'Центральный район'}</p></div></div><p>${id==='dima'?'С Ричи любим короткие спокойные прогулки.':'Люблю спокойные прогулки с питомцем и заранее обсуждаю все детали.'}</p><h2 class="section-title">Репутация как владелец</h2>${facts('owner',id)}<p class="caption">Отзывы помощников по подтверждённым прогулкам. Это отдельная оценка от опыта помощника.</p>${own?button('edit-profile','Редактировать профиль','row-button')+button('roles','Роли и режим'+icon('chevron-right'),'row-button')+(s.actor==='alex'&&s.role==='both'?button('helper-self','Опыт как помощника'+icon('chevron-right'),'row-button'):''):button('request:'+current().id,'Вернуться к запросу','primary-action')}<h2 class="section-title">Отзывы помощников</h2>${['loading','error','unavailable'].includes(s.scenario)?'<p>Отзывы сейчас недоступны.</p>':(['empty','unrated'].includes(s.scenario)||id==='dima')?'<p>Пока нет отзывов как о владельце.</p>':`${review?reviewTile({id:'luna-owner',author:'Александра',rating:review.rating,body:review.body,date:'11 октября 2026',reply:''},own):''}${reviewTile({id:'owner-old-'+id,author:'Дмитрий',rating:5,body:id==='alex'?'Александра заранее рассказала о привычках Мило. Время прогулки было понятным.':'Виктория заранее рассказала о привычках Луны. Передача питомца и время прогулки были понятными.',date:'2 октября 2026',reply:'Спасибо за помощь с Луной!'},own)}`}`,own,own);}
  function reviewForm(){const eligible=participant()&&s.stage==='completed', key=isOwner()?'helper':'owner', target=isOwner()?'Александра':'Виктория';if(!eligible)return page('Отзыв о прогулке','',`<section class="empty-state"><h2>Отзыв пока недоступен</h2><p>Отзыв может оставить только участник после подтверждения завершения владельцем.</p>${button('agreement','Открыть договорённость','primary-action')}</section>`);if(s.reviews[key])return page('Ваш отзыв','',`<p class="notice">${icon('circle-check')}Вы уже оставили отзыв по этой прогулке.</p>${button('agreement','К договорённости','primary-action')}`);const d=s.drafts['review:'+key]||{rating:'',body:''};return page(isOwner()?'Отзыв о помощнике':'Отзыв о владельце',`${target} · прогулка с Луной, 11 октября`, `<form data-form="review" class="form-group"><fieldset ${s.busy?'disabled':''}><label for="review-rating">Оценка<select id="review-rating" name="rating" required><option value="">Выберите от 1 до 5</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${d.rating==n?'selected':''}>${n} из 5</option>`).join('')}</select></label>${textarea('review-body','Как прошла прогулка?',d.body,'maxlength="1000"')}<p class="caption">Отзыв будет публичным. Не указывайте адреса, контакты и личные инструкции. Один отзыв от каждого участника по завершённой договорённости.</p></fieldset><button class="primary-action" ${s.busy?'disabled':''}>${s.busy?'Публикуем…':'Опубликовать отзыв'}</button></form>`);}
  function report(){return page('Пожаловаться',s.reportTarget?.startsWith('review')?'На отзыв':'На профиль',`<form data-form="report" class="form-group">${textarea('report-body','Что произошло?',s.drafts.report||'','maxlength="1000" required '+(s.busy?'disabled':''))}<p class="caption">Причину увидят модераторы. Не добавляйте личные адреса и контакты.</p><button class="primary-action" ${s.busy?'disabled':''}>${s.busy?'Отправляем…':'Отправить жалобу'}</button></form>`);}
  function ownerPersonal() {
    const id=s.actor, r=id==='alex'?requests[2]:requests[0];
    return page('Вы, питомцы и ваши истории.','',`
      <section class="owner-identity section">
        <div class="identity">${avatar(id)}<div class="identity-copy"><h2>${esc(fullName(id))}</h2><p class="caption">Минск · ${id==='alex'?esc(s.intro.district):'Центральный район'}</p></div></div>
        ${button('edit-profile','Редактировать профиль'+icon('pencil'),'row-button')}
        <h2>Мои питомцы</h2><div class="request-head">${pet(r)}<div class="pet-copy"><h3>${r.name}</h3><p class="caption">${r.kind}</p></div></div>
      </section>
      ${button('owner-reputation','Репутация как владелец'+icon('chevron-right'),'row-button')}
      <div class="tabs" role="tablist" aria-label="Содержимое профиля">${[['favorites','Избранное'],['walking','Выгул']].map(([value,label])=>button('owner-tab:'+value,label,'',`role="tab" aria-selected="${s.ownerTab===value}"`)).join('')}</div>
      ${s.ownerTab==='favorites'?`<h2 class="section-title">Избранные места</h2><div class="identity"><span class="avatar small" aria-hidden="true">${icon('trees')}</span><div class="identity-copy"><strong>Александровский сквер</strong><p class="caption">Парк · Минск · Допуск не подтверждён</p></div></div>`:`<h2 class="section-title">Ваш опыт как помощника</h2><p>Когда вы гуляете с питомцами других владельцев.</p>${id==='alex'?facts():'<p>Пока нет отзывов как о помощнике.</p>'}${button('helper-self','Мой профиль помощника'+icon('chevron-right'),'row-button')}`}
      ${button('roles','Роли и режим'+icon('chevron-right'),'row-button')}
    `,true,true);
  }
  function ownerHelp(){if(s.actor==='vika'){s.requestId='luna';return page('Помощь с выгулом','Ваши запросы и договорённости.',`${requestRow(requests[0])}`,true,true);}return page('Помощь с выгулом','Попросите соседей о помощи или помогите сами.',`${requestRow(requests[2])}${button('mode','Переключиться на помощь с прогулками','row-button')}`,true,true);}
  function ownerHome(){return page(s.screen==='people'?'Знакомьтесь рядом.':'Хороший день для прогулки.',s.screen==='people'?'Люди, встречи и сообщества.':'И новой компании для вас двоих.',s.screen==='people'?`<div class="identity">${avatar('vika')}<div><h2>Виктория и Луна</h2><p>Центральный район</p></div></div>${button('owner:vika','Профиль владельца','row-button')}`:`<section class="section"><h2>Встречи рядом</h2><p>В Минске пока нет встреч.</p></section><h2 class="section-title">Места рядом · Минск</h2><p class="caption">Карта в этом прототипе не подключена.</p>`,true,true);}
  function modal(){if(!s.dialog)return '';const mode=s.dialog==='mode';return `<dialog open class="menu" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${mode?'Ваш режим':s.dialog==='select'?'Выбрать Александру?':s.dialog==='block'?'Заблокировать пользователя?':'Фото профиля'}</h2>${mode?`<p>Один аккаунт. Все ваши переписки и история остаются с вами.</p>${button('mode:owner',icon('user-round')+'Владелец','row-button',`aria-pressed="${s.mode==='owner'}"`)}${button('mode:helper',icon('paw-print')+'Помощник','row-button',`aria-pressed="${s.mode==='helper'}"`)}`:s.dialog==='select'?`<p>Вы создадите договорённость с Александрой. Сначала обсудите опыт и привычки Луны. Оценки не гарантируют безопасность.</p>${button('confirm-helper','Выбрать помощника','primary-action')}`:s.dialog==='block'?`<p>Личная переписка с этим пользователем будет недоступна.</p>${button('confirm-block','Заблокировать','soft-action destructive')}`:`<p>В дизайне можно выбрать пример фото или оставить инициалы. Загрузка файлов не подключена.</p>${button('sample-photo','Использовать фото примера','soft-action')}${button('no-photo','Оставить инициалы','quiet-action')}`}${button('close-dialog','Отмена')}</dialog>`;}
  const notes={role:['Один аккаунт, разные задачи','Роль описывает намерение, а не создаёт второй профиль. Помощнику не нужен питомец. Обе роли получают явное переключение в шапке.'],onboarding:['Короткое знакомство','Два шага: публичная личность, затем необязательные предпочтения. Район публичный; точного домашнего адреса нет. Все новые поля помечены в спецификации.'],requests:['Запрос, который вам подходит','Питомец → время и район → владелец → действие. Репутация владельца подписана отдельно. Фильтры имеют постоянные подписи. Список никогда не раскрывает адрес передачи.'],request:['Отклик — ещё не прогулка','Отправка отклика не назначает помощника. Только владелец выбирает кандидата. После выбора доступен приватный чат договорённости.'], 'my-walks':['Договорённости отдельно от откликов','Назначенные прогулки и отправленные отклики — разные списки. История вторична. На каждом соглашении видна роль, состояние и следующий допустимый шаг.'],agreement:['Один следующий шаг','Помощник начинает и завершает; владелец подтверждает. Ожидание второго участника обозначено текстом. Здесь нет новых правил отмены или спора.'],chat:['Контекст рядом с разговором','Отправитель и время у каждого сообщения; контекст прогулки ведёт к договорённости. Только назначенные участники видят этот чат. Текст и фото; видео вне проекта.'],profile:['Опыт именно как помощника','Рейтинг, опубликованные отзывы и завершённые выгулы описывают помощь другим владельцам. Предпочтения вторичны. В собственном профиле редактирование и ответы; нет контакта с самим собой.'], 'owner-profile':['Отдельная репутация владельца','Новая предлагаемая функция. Отзывы помощников по подтверждённым прогулкам отдельно от рейтинга помощника и мест. Ни одного значка безопасности.'],review:['Взаимный отзыв после подтверждения','Только два участника и только подтверждённая договорённость. По одному отзыву друг о друге. Проект не задаёт сроки публикации. Черновик остаётся при ошибке и возвращении.']};
  function render(focus=false){const scroll=root.querySelector('.page')?.scrollTop||0;const n=notes[s.screen]||notes.profile;document.querySelector('#notes-heading').textContent=n[0];document.querySelector('#notes').innerHTML=`<p>${n[1]}</p><p>Просмотр: ${s.actor==='alex'?'Александра, один аккаунт с обеими ролями':'Виктория, другой участник примера'}. Все действия локальны.</p>`;phone.dataset.theme=s.theme;phone.dataset.scale=s.scale;phone.dataset.platform=s.platform;phone.style.setProperty('--phone-width',s.width+'px');phone.style.setProperty('--text-scale',s.scale);Object.entries(controls).forEach(([k,el])=>{if(k==='failure')el.checked=s.fail;else if(k==='screen'){if([...el.options].some(o=>o.value===s.screen))el.value=s.screen;}else if(s[k]!==undefined)el.value=s[k];});const views={role:roleScreen,onboarding,requests:requestsScreen,request:requestDetail,'my-walks':myWalks,agreement,chats,chat:()=>chat(false),'direct-chat':()=>chat(true),profile:()=>helperProfile(false),'public-helper':()=>helperProfile(true),'owner-profile':()=>ownerProfile(false),'owner-self':ownerPersonal,review:reviewForm,report,'owner-help':ownerHelp,nearby:ownerHome,people:ownerHome};root.innerHTML=(views[s.screen]||requestsScreen)()+modal();window.lucide?.createIcons();const page=root.querySelector('.page');if(page){page.scrollTop=focus?0:scroll;if(focus)page.focus({preventScroll:true});}if(s.dialog){[...root.children].filter(el=>el.tagName!=='DIALOG').forEach(el=>el.inert=true);const dialog=root.querySelector('dialog');dialog.querySelector('button')?.focus({preventScroll:true});} }
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||s.busy)return;const [a,b,c]=el.dataset.action.split(':');switch(a){case'nav':s.back=[];s.screen=b;s.feedback='';s.menu=false;render(true);break;case'back':back();break;case'theme':s.theme=s.theme==='light'?'dark':'light';render();break;case'mode':if(b){s.mode=b;s.dialog=null;s.back=[];s.screen=b==='helper'?'requests':'owner-help';s.feedback='';render(true);}else{s.dialog='mode';render();}break;case'close-dialog':s.dialog=null;render();break;case'photo':s.dialog='photo';render();break;case'sample-photo':s.dialog=null;s.scenario='populated';render();break;case'no-photo':s.dialog=null;s.scenario='long';render();break;case'onboard-skip':s.onboardingDone=true;s.screen='requests';render(true);break;case'requests-home':s.screen='requests';s.scenario='populated';s.back=[];render(true);break;case'reset-filters':s.scenario='populated';s.filters={city:'Минск',district:'Все районы',date:'Любая дата',when:'Любое время',size:'Любой размер'};render();break;case'request':s.requestId=b;go('request');break;case'owner':s.ownerId=b;go('owner-profile');break;case'candidate':s.candidateId=b;go('public-helper');break;case'apply':if(isOwner()||(s.requestId==='luna'?s.stage!=='available':s.applications[s.actor+':'+s.requestId]))return;operate(()=>{if(s.requestId==='luna')s.stage='applied';else s.applications[s.actor+':'+s.requestId]=true;s.feedback='Отклик отправлен. Дождитесь решения владельца.';});break;case'withdraw':if(s.requestId==='luna'?s.stage!=='applied':!s.applications[s.actor+':'+s.requestId])return;operate(()=>{if(s.requestId==='luna')s.stage='available';else delete s.applications[s.actor+':'+s.requestId];s.feedback='Отклик отозван.';});break;case'select-helper':s.dialog='select';render();break;case'confirm-helper':if(!isOwner()||s.stage!=='applied')return;s.dialog=null;operate(()=>{s.stage='selected';s.screen='agreement';s.feedback='Помощник выбран. Обсудите передачу питомца в чате.';});break;case'agreement':s.requestId='luna';go('agreement');break;case'start':if(s.actor!=='alex'||s.stage!=='selected')return;operate(()=>{s.stage='active';s.feedback='Прогулка началась.';});break;case'finish':if(s.actor!=='alex'||s.stage!=='active')return;operate(()=>{s.stage='awaiting';s.feedback='Виктория получила уведомление о завершении.';});break;case'confirm':if(!isOwner()||s.stage!=='awaiting')return;operate(()=>{s.stage='completed';s.feedback='Прогулка подтверждена. Можно оставить отзыв.';});break;case'review':go('review');break;case'tab':s.tab=b;render(true);break;case'chat':go('chat');break;case'direct-chat':s.contactTarget=b||'dima';if(s.blocks[s.actor+':'+s.contactTarget]){s.feedback='Переписка с заблокированным пользователем недоступна.';s.feedbackError=true;render();return;}operate(()=>{s.back.push({screen:s.screen});s.screen='direct-chat';},'Не удалось открыть переписку. Попробуйте снова.');break;case'edit-profile':s.ownerEditing=s.mode==='owner';s.step=0;go('onboarding');break;case'owner-tab':s.ownerTab=b;render();break;case'owner-reputation':s.ownerId=s.actor;go('owner-profile');break;case'roles':go('role');break;case'helper-self':go('profile');break;case'owner-self':go('owner-self');break;case'expand':s.expanded[b]=!s.expanded[b];render();break;case'reply':s.replyId=b;render();root.querySelector('#reply-text')?.focus();break;case'close-reply':s.replyId=null;render();break;case'profile-menu':s.menu=!s.menu;render();break;case'report':s.reportTarget=b+':'+c;go('report');break;case'block':s.blockTarget=b||'dima';s.dialog='block';render();break;case'confirm-block':s.dialog=null;operate(()=>{s.blocks[s.actor+':'+s.blockTarget]=true;s.feedback='Пользователь заблокирован.';s.menu=false;});break;case'message-photo':s.draftPhotos[messageKey()]=true;render();break;case'remove-photo':delete s.draftPhotos[messageKey()];render();break;case'retry':operate(()=>{s.scenario='populated';},'Данные всё ещё не загрузились. Повторите попытку.');break;} });
  root.addEventListener('input',e=>{const name=e.target.name;if(name==='message')s.drafts[messageKey()]=e.target.value;if(name==='reply-text')s.drafts['reply:'+s.replyId]=e.target.value;if(name==='report-body')s.drafts.report=e.target.value;if(['rating','review-body'].includes(name)){const k=isOwner()?'helper':'owner';s.drafts['review:'+k]={rating:root.querySelector('#review-rating')?.value||'',body:root.querySelector('#review-body')?.value||''};}if(name in editingIntro()&&name!=='sizes')editingIntro()[name]=e.target.value;});
  root.addEventListener('change',e=>{if(e.target.dataset.filter){s.filters[e.target.dataset.filter]=e.target.value;render();}if(e.target.name==='role')s.roleDraft=e.target.value;if(e.target.name==='sizes')editingIntro().sizes=[...root.querySelectorAll('[name="sizes"]:checked')].map(el=>el.value);if(e.target.name==='rating'){const k=isOwner()?'helper':'owner';s.drafts['review:'+k]={rating:e.target.value,body:root.querySelector('#review-body')?.value||''};}});
  root.addEventListener('submit',e=>{e.preventDefault();if(s.busy)return;const form=e.target;if(!form.reportValidity())return;const values=new FormData(form);switch(form.dataset.form){case'role':s.ownerEditing=false;operate(()=>{s.role=values.get('role');s.roleByActor[s.actor]=s.role;s.roleDraft=null;s.mode=s.role==='owner'?'owner':'helper';s.screen=s.role==='owner'?'owner-help':s.onboardingDone?'requests':'onboarding';s.step=0;});break;case'onboarding':for(const k in editingIntro())if(k!=='sizes'&&values.has(k))editingIntro()[k]=values.get(k);operate(()=>{if(s.ownerEditing){s.screen='owner-self';s.ownerEditing=false;}else if(s.step===0)s.step=1;else{s.onboardingDone=true;s.screen=s.mode==='helper'?'requests':'owner-help';}});break;case'message':{const text=String(values.get('message')||'').trim();if(!text&&!s.draftPhotos[messageKey()]){s.feedback='Напишите сообщение или прикрепите фото.';s.feedbackError=true;render();return;}operate(()=>{const key=messageKey();s.messages.push({actor:s.actor,text,photo:!!s.draftPhotos[key],time:'18:05',direct:s.screen==='direct-chat',target:s.contactTarget});s.drafts[key]='';delete s.draftPhotos[key];});break;}case'review':{const key=isOwner()?'helper':'owner';if(!participant()||s.stage!=='completed'||s.reviews[key])return;const rating=Number(values.get('rating')),body=String(values.get('review-body')).trim();if(rating<1||rating>5)return;operate(()=>{s.reviews[key]={rating,body};delete s.drafts['review:'+key];s.screen='agreement';s.feedback='Отзыв опубликован.';});break;}case'reply':{const id=form.dataset.review,body=String(values.get('reply-text')).trim();if(!body)return;operate(()=>{s.replies[id]=body;delete s.drafts['reply:'+id];s.replyId=null;s.feedback='Ответ опубликован.';});break;}case'report':operate(()=>{s.drafts.report='';s.screen=s.back.pop()?.screen||'profile';s.feedback='Жалоба отправлена модераторам.';});break;}});
  root.addEventListener('keydown',e=>{if(e.key==='Tab'&&s.dialog){const items=[...root.querySelectorAll('dialog button:not(:disabled), dialog input, dialog select, dialog textarea')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&s.dialog&&!s.busy){s.dialog=null;render();}if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();s.tab=e.key==='Home'?'upcoming':e.key==='End'?'applications':s.tab==='upcoming'?'applications':'upcoming';render();root.querySelector('[role="tab"][aria-selected="true"]')?.focus();}});
  document.querySelector('.preview-controls').addEventListener('submit',e=>e.preventDefault());
  Object.entries(controls).forEach(([key,el])=>el.addEventListener('change',()=>{if(s.busy){el.value=s[key];return;}if(key==='failure'){s.fail=el.checked;return;}s[key]=el.value;s.feedback='';s.menu=false;s.dialog=null;if(key==='actor'){s.role=s.roleByActor[s.actor];s.roleDraft=null;s.mode=s.actor==='vika'?'owner':'helper';s.screen=s.actor==='vika'?'owner-help':'my-walks';s.back=[];s.requestId='luna';}if(key==='screen'&&s.screen==='public-helper')s.candidateId=s.actor==='alex'?'dima':'alex';if(key==='screen'&&s.screen==='owner-profile')s.ownerId='vika';if(key==='screen'&&s.screen==='owner-self')s.mode='owner';if(key==='screen'&&['requests','my-walks','profile'].includes(s.screen))s.mode='helper';if(key==='stage')s.requestId='luna';render(true);}));
  document.querySelector('#reset-flow').addEventListener('click',()=>{if(s.busy)return;s.actor='alex';s.role='both';s.roleDraft=null;s.roleByActor={alex:'both',vika:'owner'};s.mode='helper';s.stage='available';s.screen='role';s.requestId='luna';s.scenario='populated';s.back=[];s.feedback='';s.dialog=null;s.reviews={};s.replies={};s.drafts={};s.messages=[];s.blocks={};s.draftPhotos={};s.applications={};s.tab='upcoming';s.step=0;render(true);});
  const params=new URLSearchParams(location.search);
  for(const key of ['screen','scenario','theme','width','scale','platform','actor','stage']) {
    const value=params.get(key);
    if(value&&[...controls[key].options].some(option=>option.value===value))s[key]=value;
  }
  if(s.actor==='vika'){s.role='owner';s.mode='owner';}
  if(s.screen==='public-helper')s.candidateId=s.actor==='alex'?'dima':'alex';
  if(s.screen==='owner-profile')s.ownerId='vika';if(s.screen==='owner-self')s.mode='owner';
  if(params.get('presentation')==='phone')document.body.classList.add('presentation-phone');
  render();
})();
